using App.Entities;
using Microsoft.EntityFrameworkCore;

namespace App;

/// <summary>The tables of the database, mapped as the database has them. It never migrates: the database already exists.</summary>
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Thing> Things => Set<Thing>();
    public DbSet<Kind> Kinds => Set<Kind>();
    public DbSet<Order> OrderRows => Set<Order>();
    public DbSet<AuditEntry> AuditEntries => Set<AuditEntry>();
    public DbSet<Empty> Empties => Set<Empty>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<Thing>(entity =>
        {
            entity.ToTable("things");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("id");
            entity.Property(e => e.Tiny).HasColumnName("tiny");
            entity.Property(e => e.Small).HasColumnName("small");
            entity.Property(e => e.Medium).HasColumnName("medium");
            entity.Property(e => e.Num).HasColumnName("num");
            entity.Property(e => e.Big).HasColumnName("big");
            entity.Property(e => e.Price).HasColumnName("price").HasPrecision(10, 2);
            entity.Property(e => e.R).HasColumnName("r");
            entity.Property(e => e.D).HasColumnName("d");
            entity.Property(e => e.Flag).HasColumnName("flag").IsRequired().HasDefaultValue(true);
            entity.Property(e => e.Born).HasColumnName("born");
            entity.Property(e => e.Opens).HasColumnName("opens");
            entity.Property(e => e.At).HasColumnName("at");
            entity.Property(e => e.AtTs).HasColumnName("at_ts").IsRequired().HasDefaultValueSql("CURRENT_TIMESTAMP(6)");
            entity.Property(e => e.Changed).HasColumnName("changed").HasDefaultValueSql("CURRENT_TIMESTAMP(6)");
            entity.Property(e => e.Bin).HasColumnName("bin").HasMaxLength(50);
