{
    public IThingRepository Things { get; } = new MemoryThingRepository();
    public IKindRepository Kinds { get; } = new MemoryKindRepository();
    public IOrderRepository OrderRows { get; } = new MemoryOrderRepository();
    public IAuditEntryRepository AuditEntries { get; } = new MemoryAuditEntryRepository();
    public IEmptyRepository Empties { get; } = new MemoryEmptyRepository();

    /// <summary>Memory has no transactions: changes are kept as they are made.</summary>
    public Task<T> TransactionAsync<T>(Func<IUnitOfWork, Task<T>> work) => work(this);

    public Task TransactionAsync(Func<IUnitOfWork, Task> work) =>
        TransactionAsync<bool>(async uow =>
        {
            await work(uow);
            return true;
        });
}

