using App.Common;
using App.Entities;

namespace App.Repositories;

/// <summary>Keeps audit_entries rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryAuditEntryRepository : IAuditEntryRepository
{
    private readonly Dictionary<string, AuditEntry> rows = [];
    private long nextId = 1;

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(AuditEntry row) => [row.EntryNo];

    private static string KeyText(AuditEntry row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<AuditEntry> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<AuditEntry?> FindByEntryNoAsync(int entryNo)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.EntryNo, entryNo)));
    }

    public Task<Page<AuditEntry>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<AuditEntry>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<List<AuditEntry>> ListByOrderIdAsync(long orderId)
    {
        return Task.FromResult(Visible().Where(row => Equals(row.OrderId, orderId)).ToList());
    }

    public Task<AuditEntry> InsertAsync(AuditEntry entity)
    {
        if (entity.EntryNo == 0) entity.EntryNo = (int)nextId++;
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<AuditEntry> UpdateAsync(AuditEntry entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(AuditEntry entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }
}

