using App.Errors;

namespace App.Services;

/// <summary>Operations on audit_entries. Each write runs in its own transaction.</summary>
public class AuditEntryService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "audit_entries" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, AuditEntry? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("OrderId");
            if (value is null)
                if (creating || values.ContainsKey("OrderId")) errors.Add(new FieldError("orderId", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Message");
            if (value is null)
            {
                if (creating || values.ContainsKey("Message")) errors.Add(new FieldError("message", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 200) errors.Add(new FieldError("message", "is longer than 200 characters"));
            }
        }
        {
            var orderId = values.TryGetValue("OrderId", out var givenOrderId) ? (long?)givenOrderId : current?.OrderId;
            if (orderId is not null && await uow.OrderRows.FindByIdAsync(orderId.Value) is null)
                errors.Add(new FieldError("orderId", "no Order has this key"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("AuditEntry", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, AuditEntry? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(AuditEntry entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("OrderId", out var orderId)) entity.OrderId = (long)orderId!;
        if (values.TryGetValue("Message", out var message)) entity.Message = (string)message!;
    }

    /// <summary>The AuditEntry with this key; NotFoundException when there is none.</summary>
    private static async Task<AuditEntry> FindAsync(IUnitOfWork uow, int entryNo) =>
        await uow.AuditEntries.FindByEntryNoAsync(entryNo) ?? throw new NotFoundException("AuditEntry", entryNo);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(AuditEntryChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.OrderId is { IsPresent: true } orderId) values["OrderId"] = orderId.Value;
        if (changes.Message is { IsPresent: true } message) values["Message"] = message.Value;
        return values;
    }

    /// <summary>Stores a new AuditEntry after checking it.</summary>
    public async Task<AuditEntry> CreateAuditEntryAsync(AuditEntry auditEntry)
    {
        var values = new Dictionary<string, object?>();
        values["OrderId"] = auditEntry.OrderId;
        if (auditEntry.Message is not null) values["Message"] = auditEntry.Message;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.AuditEntries.InsertAsync(auditEntry);
        });
    }

    /// <summary>The AuditEntry with this key; NotFoundException when there is none.</summary>
    public async Task<AuditEntry> GetAuditEntryAsync(int entryNo) => await FindAsync(uow, entryNo);

    /// <summary>A page of audit_entries, by primary key.</summary>
    public async Task<Page<AuditEntry>> ListAuditEntriesAsync(int offset, int limit) => await uow.AuditEntries.ListAsync(offset, limit);

    /// <summary>Changes the given values of a AuditEntry.</summary>
    public async Task<AuditEntry> UpdateAuditEntryAsync(int entryNo, AuditEntryChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, entryNo);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return await uow.AuditEntries.UpdateAsync(current);
        });
    }

    /// <summary>Deletes a AuditEntry.</summary>
    public async Task DeleteAuditEntryAsync(int entryNo)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, entryNo);
            await uow.AuditEntries.DeleteAsync(current);
        });
    }

    /// <summary>The audit_entries with this orderId.</summary>
    public async Task<List<AuditEntry>> ListAuditEntriesByOrderIdAsync(long orderId) => await uow.AuditEntries.ListByOrderIdAsync(orderId);
}

