    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "Order" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Order? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("User");
            if (value is null)
            {
                if (creating || values.ContainsKey("User")) errors.Add(new FieldError("user", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 40) errors.Add(new FieldError("user", "is longer than 40 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("Group");
            if (value is null)
            {
                if (!creating && values.ContainsKey("Group")) errors.Add(new FieldError("group", "cannot be empty"));
            }
            else
            {
                if (!(Number(value) >= 0m)) errors.Add(new FieldError("group", "must be >= 0"));
            }
        }
        {
            var value = values.GetValueOrDefault("CustomerName");
            if (value is null)
            {
                if (creating || values.ContainsKey("CustomerName")) errors.Add(new FieldError("customerName", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 60) errors.Add(new FieldError("customerName", "is longer than 60 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("Text");
            if (value is not null)
            {
                if (value is string text && text.Length > 20) errors.Add(new FieldError("text", "is longer than 20 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("Str");
            if (value is not null)
            {
                if (value is string text && text.Length > 10) errors.Add(new FieldError("str", "is longer than 10 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("DueDate");
            if (value is null)
                if (creating || values.ContainsKey("DueDate")) errors.Add(new FieldError("dueDate", "is required"));
        }
        {
            var value = values.GetValueOrDefault("KindCode");
            if (value is not null)
            {
                if (value is string text && text.Length > 10) errors.Add(new FieldError("kind_code", "is longer than 10 characters"));
            }
        }
        {
            var thingId = values.TryGetValue("ThingId", out var givenThingId) ? (Guid?)givenThingId : current?.ThingId;
            if (thingId is not null && await uow.Things.FindByIdAsync(thingId.Value) is null)
                errors.Add(new FieldError("thing_id", "no Thing has this key"));
        }
        {
            var parentId = values.TryGetValue("ParentId", out var givenParentId) ? (long?)givenParentId : current?.ParentId;
            if (parentId is not null && await uow.OrderRows.FindByIdAsync(parentId.Value) is null)
                errors.Add(new FieldError("parentId", "no Order has this key"));
        }
        {
            var kindCode = values.TryGetValue("KindCode", out var givenKindCode) ? (string?)givenKindCode : current?.KindCode;
            var kindDay = values.TryGetValue("KindDay", out var givenKindDay) ? (DateOnly?)givenKindDay : current?.KindDay;
            if (kindCode is not null && kindDay is not null && await uow.Kinds.FindByCodeAndDayAsync(kindCode, kindDay.Value) is null)
                errors.Add(new FieldError("kind_code, kind_day", "no Kind has this key"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("Order", errors);
    }

    /// <summary>A number of any type, to compare it.</summary>
    private static decimal Number(object value) => Convert.ToDecimal(value, CultureInfo.InvariantCulture);

    /// <summary>Values that must be unique are not taken by another row.</summary>
    private static async Task CheckUniqueAsync(IUnitOfWork uow, Dictionary<string, object?> values, Order? current)
    {
        {
            var customerName = values.TryGetValue("CustomerName", out var givenCustomerName) ? (string?)givenCustomerName : current?.CustomerName;
            if (customerName is not null)
            {
                var other = await uow.OrderRows.FindByCustomerNameAsync(customerName);
                if (other is not null && (current is null || !Equals(other.Id, current.Id)))
                    throw new ConflictException("Order", "customerName is already taken", ["CustomerName"]);
            }
        }
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Order? current)
    {
        await ValidateAsync(uow, values, current);
        await CheckUniqueAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Order entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("User", out var user)) entity.User = (string)user!;
        if (values.TryGetValue("Group", out var group)) entity.Group = (int?)group;
        if (values.TryGetValue("CustomerName", out var customerName)) entity.CustomerName = (string)customerName!;
        if (values.TryGetValue("Class", out var @class)) entity.Class = (string?)@class;
        if (values.TryGetValue("Metadata", out var metadata)) entity.Metadata = (string?)metadata;
        if (values.TryGetValue("Date", out var date)) entity.Date = (DateOnly?)date;
        if (values.TryGetValue("Time", out var time)) entity.Time = (TimeOnly?)time;
        if (values.TryGetValue("Text", out var text)) entity.Text = (string?)text;
        if (values.TryGetValue("List", out var list)) entity.List = (string?)list;
        if (values.TryGetValue("Str", out var str)) entity.Str = (string?)str;
        if (values.TryGetValue("Int", out var @int)) entity.Int = (int?)@int;
        if (values.TryGetValue("DueDate", out var dueDate)) entity.DueDate = (DateOnly)dueDate!;
        if (values.TryGetValue("ClosesAt", out var closesAt)) entity.ClosesAt = (TimeOnly?)closesAt;
        if (values.TryGetValue("KindCode", out var kindCode)) entity.KindCode = (string?)kindCode;
        if (values.TryGetValue("KindDay", out var kindDay)) entity.KindDay = (DateOnly?)kindDay;
        if (values.TryGetValue("ThingId", out var thingId)) entity.ThingId = (Guid?)thingId;
        if (values.TryGetValue("ParentId", out var parentId)) entity.ParentId = (long?)parentId;
    }

    /// <summary>The Order with this key; NotFoundException when there is none.</summary>
    private static async Task<Order> FindAsync(IUnitOfWork uow, long id) =>
        await uow.OrderRows.FindByIdAsync(id) ?? throw new NotFoundException("Order", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(OrderChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.User is { IsPresent: true } user) values["User"] = user.Value;
        if (changes.Group is { IsPresent: true } group) values["Group"] = group.Value;
        if (changes.CustomerName is { IsPresent: true } customerName) values["CustomerName"] = customerName.Value;
        if (changes.Class is { IsPresent: true } @class) values["Class"] = @class.Value;
