        if (order.User is not null) values["User"] = order.User;
        if (order.Group is not null) values["Group"] = order.Group;
        if (order.CustomerName is not null) values["CustomerName"] = order.CustomerName;
        if (order.Class is not null) values["Class"] = order.Class;
        if (order.Metadata is not null) values["Metadata"] = order.Metadata;
        if (order.Date is not null) values["Date"] = order.Date;
        if (order.Time is not null) values["Time"] = order.Time;
        if (order.Text is not null) values["Text"] = order.Text;
        if (order.List is not null) values["List"] = order.List;
        if (order.Str is not null) values["Str"] = order.Str;
        if (order.Int is not null) values["Int"] = order.Int;
        values["DueDate"] = order.DueDate;
