        if (order.KindCode is not null) values["KindCode"] = order.KindCode;
        if (order.KindDay is not null) values["KindDay"] = order.KindDay;
        if (order.ThingId is not null) values["ThingId"] = order.ThingId;
        if (order.ParentId is not null) values["ParentId"] = order.ParentId;
