namespace App.Tests;

/// <summary>The repository of the "audit_entries" table, against the test database.</summary>
public class AuditEntryRepositoryTests : IAsyncLifetime
{
    private TestDatabase database = null!;

    /// <summary>The repositories over the test database, opened empty for every test</summary>
    private SqlUnitOfWork uow = null!;

    public async ValueTask InitializeAsync()
    {
        database = await TestDatabase.OpenAsync();
        uow = new SqlUnitOfWork(database.Db);
    }

    public async ValueTask DisposeAsync() => await database.DisposeAsync();

    [Fact]
    public async Task IsStoredAndReadBack()
    {
        var stored = await Factories.AddAuditEntryAsync(uow, 1);
        uow.Db.ChangeTracker.Clear();
        var found = await uow.AuditEntries.FindByEntryNoAsync(stored.EntryNo);
        Assert.NotNull(found);
        Assert.Equal(stored.EntryNo, found.EntryNo);
        Assert.Single(await uow.AuditEntries.ListByOrderIdAsync(stored.OrderId));
    }

    [Fact]
    public async Task ListsRowsByKey()
    {
        await Factories.AddAuditEntryAsync(uow, 1);
        await Factories.AddAuditEntryAsync(uow, 2);
        var page = await uow.AuditEntries.ListAsync(0, 1);
        Assert.Equal(2, page.Total);
        Assert.Single(page.Items);
    }

    [Fact]
    public async Task StoresTheChanges()
    {
        var stored = await Factories.AddAuditEntryAsync(uow, 1);
        stored.Message = "changed";
        await uow.AuditEntries.UpdateAsync(stored);
        uow.Db.ChangeTracker.Clear();
        Assert.Equal("changed", (await uow.AuditEntries.FindByEntryNoAsync(stored.EntryNo))!.Message);
    }

    [Fact]
    public async Task IsDeleted()
    {
        var stored = await Factories.AddAuditEntryAsync(uow, 1);
        await uow.AuditEntries.DeleteAsync(stored);
        Assert.Null(await uow.AuditEntries.FindByEntryNoAsync(stored.EntryNo));
    }
}

