    [Fact]
    public async Task IsStoredAndReadBack()
    {
        var stored = await Factories.AddThingAsync(uow, 1);
        uow.Db.ChangeTracker.Clear();
        var found = await uow.Things.FindByIdAsync(stored.Id);
        Assert.NotNull(found);
        Assert.Equal(stored.Id, found.Id);
    }

    [Fact]
    public async Task ListsRowsByKey()
    {
        await Factories.AddThingAsync(uow, 1);
        await Factories.AddThingAsync(uow, 2);
        var page = await uow.Things.ListAsync(0, 1);
        Assert.Equal(2, page.Total);
        Assert.Single(page.Items);
    }

    [Fact]
    public async Task StoresTheChanges()
    {
        var stored = await Factories.AddThingAsync(uow, 1);
        stored.Note = "changed";
        await uow.Things.UpdateAsync(stored);
        uow.Db.ChangeTracker.Clear();
        Assert.Equal("changed", (await uow.Things.FindByIdAsync(stored.Id))!.Note);
    }

    [Fact]
    public async Task IsDeleted()
    {
        var stored = await Factories.AddThingAsync(uow, 1);
        await uow.Things.DeleteAsync(stored);
        Assert.Null(await uow.Things.FindByIdAsync(stored.Id));
    }
}

/// <summary>The service of the "things" table, on the in-memory repositories.</summary>
public class ThingServiceTests
{
    private readonly MemoryUnitOfWork uow = new();

    [Fact]
    public async Task CreatesAValidRow()
    {
        var service = new ThingService(uow);
        var n = 100;
        var row = Factories.NewThing(1);
        var created = await service.CreateThingAsync(row);
        var found = await service.GetThingAsync(created.Id);
        Assert.Equal(created.Id, found.Id);
    }

    [Fact]
    public async Task RefusesAMissingValue()
    {
        var service = new ThingService(uow);
        var n = 100;
        var row = Factories.NewThing(1);
        row.Bin = null!;
        var error = await Assert.ThrowsAsync<ValidationFailedException>(() => service.CreateThingAsync(row));
        Assert.Equal(new[] { "bin" }, error.Errors.Select(item => item.Field));
    }

    [Fact]
    public async Task SaysWhenARowIsMissing()
    {
        var service = new ThingService(uow);
        await Assert.ThrowsAsync<NotFoundException>(() => service.GetThingAsync(Guid.Parse("00000000-0000-4000-8000-000000999999")));
    }

    [Fact]
    public async Task ChangesARow()
    {
        var service = new ThingService(uow);
        var n = 100;
        var row = Factories.NewThing(1);
        var created = await service.CreateThingAsync(row);
        var updated = await service.UpdateThingAsync(created.Id, new ThingChanges(Patch<short>.Absent, Patch<short>.Absent, Patch<int?>.Absent, Patch<int?>.Absent, Patch<long>.Absent, Patch<decimal>.Absent, Patch<float>.Absent, Patch<double?>.Absent, Patch<bool?>.Absent, Patch<DateOnly>.Absent, Patch<TimeOnly>.Absent, Patch<DateTime>.Absent, Patch<DateTime?>.Absent, Patch<byte[]>.Absent, Patch<byte[]?>.Absent, Patch<string>.Absent, Patch<string>.Absent, Patch<string>.Absent, Patch<string?>.Of("changed"), Patch<string?>.Absent));
        Assert.Equal("changed", updated.Note);
    }

    [Fact]
    public async Task DeletesARow()
    {
        var service = new ThingService(uow);
        var n = 100;
        var row = Factories.NewThing(1);
        var created = await service.CreateThingAsync(row);
        await service.DeleteThingAsync(created.Id);
        await Assert.ThrowsAsync<NotFoundException>(() => service.GetThingAsync(created.Id));
    }
